CREATE TABLE users(userid SERIAL PRIMARY KEY,is_admin BOOLEAN NOT NULL,is_active BOOLEAN NOT NULL);
INSERT INTO users VALUES(1,true,true),(2,false,true);
CREATE TABLE customers(customerid SERIAL PRIMARY KEY,name TEXT,companyname TEXT,firstname TEXT,lastname TEXT,customertype TEXT,updated_at TIMESTAMP DEFAULT NOW(),is_archived BOOLEAN DEFAULT false);
INSERT INTO customers(customerid,name) VALUES(1,'Job test customer'),(2,'Other test customer');
CREATE TABLE status(statusid INTEGER PRIMARY KEY,status TEXT);
INSERT INTO status VALUES(1,'Planning'),(2,'Confirmed'),(4,'Completed'),(6,'Cancelled');
CREATE TABLE jobcategory(jobcategoryid SERIAL PRIMARY KEY,name TEXT);
INSERT INTO jobcategory VALUES(1,'Job test category');
CREATE TABLE venues(id SERIAL PRIMARY KEY,name TEXT,is_archived BOOLEAN DEFAULT false,updated_at TIMESTAMP DEFAULT NOW());
INSERT INTO venues(id,name) VALUES(1,'Job test venue');
CREATE TABLE jobs(jobid SERIAL PRIMARY KEY,job_code TEXT,customerid INTEGER REFERENCES customers(customerid),statusid INTEGER REFERENCES status(statusid),jobcategoryid INTEGER REFERENCES jobcategory(jobcategoryid),venue_id INTEGER REFERENCES venues(id),description TEXT,startdate DATE,enddate DATE,revenue NUMERIC(12,2) DEFAULT 0,final_revenue NUMERIC(12,2) DEFAULT 0,discount NUMERIC(10,2) DEFAULT 0,discount_type TEXT DEFAULT 'amount',multiply_by_days BOOLEAN DEFAULT true,prices_include_tax BOOLEAN DEFAULT false,created_by INTEGER,updated_by INTEGER,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW(),deleted_at TIMESTAMP);
CREATE TABLE audit_log(id BIGSERIAL PRIMARY KEY,user_id INTEGER,action TEXT,entity_type TEXT,entity_id TEXT,old_values JSONB,new_values JSONB,timestamp TIMESTAMPTZ);
CREATE TABLE rental_mcp_mutation_receipts(id BIGSERIAL PRIMARY KEY,user_id INTEGER,operation TEXT,key_hash TEXT,request_hash TEXT,response JSONB,status_code INTEGER,UNIQUE(user_id,operation,key_hash));
CREATE TABLE job_history(history_id BIGSERIAL PRIMARY KEY,job_id INTEGER,user_id INTEGER,change_type TEXT,field_name TEXT,old_value TEXT,new_value TEXT,description TEXT);
CREATE TABLE devices(deviceid TEXT PRIMARY KEY,productid INTEGER,status TEXT,condition_status TEXT DEFAULT 'ok',updated_at TIMESTAMP DEFAULT NOW());
INSERT INTO devices(deviceid,status) VALUES('JOB-TEST-DEVICE','free');
CREATE TABLE job_devices(jobid INTEGER,deviceid TEXT,pack_status TEXT DEFAULT 'pending',PRIMARY KEY(jobid,deviceid));
CREATE TABLE job_product_requirements(id SERIAL PRIMARY KEY,job_id INTEGER,product_id INTEGER,quantity INTEGER);
CREATE TABLE job_packages(job_package_id SERIAL PRIMARY KEY,job_id INTEGER,package_id INTEGER,quantity INTEGER);
CREATE TABLE job_positions(position_id SERIAL PRIMARY KEY,job_id INTEGER,quantity NUMERIC,unit_price NUMERIC,follow_day_factor NUMERIC,discount_percent NUMERIC DEFAULT 0,discount_amount NUMERIC DEFAULT 0,tax_rate NUMERIC DEFAULT 0,updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE job_rental_equipment(job_id INTEGER,equipment_id INTEGER,quantity INTEGER,PRIMARY KEY(job_id,equipment_id));
CREATE TABLE job_package_reservations(reservation_id SERIAL PRIMARY KEY,job_package_id INTEGER,device_id TEXT,reservation_status TEXT DEFAULT 'reserved');
CREATE TABLE job_position_devices(id SERIAL PRIMARY KEY,position_id INTEGER,device_id TEXT);
CREATE TABLE job_edit_sessions(session_id SERIAL PRIMARY KEY,job_id INTEGER,user_id INTEGER,last_seen TIMESTAMP DEFAULT NOW());
CREATE TABLE warehouse_tasks(task_id SERIAL PRIMARY KEY,job_id INTEGER,status TEXT,is_archived BOOLEAN DEFAULT false,updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE cases(caseid SERIAL PRIMARY KEY,current_job_id INTEGER,lifecycle_status TEXT DEFAULT 'active',updated_at TIMESTAMP DEFAULT NOW());
